window.FaceEffects={retrigger(element,className){if(!element)return;element.classList.remove(className);void element.offsetWidth;element.classList.add(className)},scatter(host,{count=6,x=50,y=50,className='dander-speck',spread=42}={}){for(let i=0;i<count;i++){const particle=document.createElement('i');particle.className=className;particle.style.left=(x+(Math.random()-.5)*8)+'%';particle.style.top=(y+Math.random()*4)+'%';particle.style.setProperty('--drift',((Math.random()-.5)*spread)+'px');host.append(particle);setTimeout(()=>particle.remove(),900)}}};
